// Python: simple retry wrapper example
def with_retry(fn, preset):
    attempt = 0
    while attempt < preset['attempts']:
        try:
            return fn()
        except TransientError as e:
            attempt += 1
            backoff = jittered_backoff(preset['base_delay'], attempt, preset['cap_delay'])
            sleep(backoff)
    raise

